183	            }
184	
185	            @Override
186	            public void onClosed() {
187	                super.onClosed();
188	                expandButton.setCompoundDrawablesRelativeWithIntrinsicBounds(0, 0, R.drawable.ic_arrow_down_accent, 0);
189	            }
190	        });
191	
192	        AlertDialog.Builder builder = new AlertDialog.Builder(callingActivity);
193	        builder.setTitle(R.string.dialog_title_manual_entry)
194	                .setView(inputView)
195	                .setPositiveButton(R.string.button_save, new DialogInterface.OnClickListener() {
196	                    @Override
197	                    public void onClick(DialogInterface dialogInterface, int i) {
198	                        Entry.OTPType type = (Entry.OTPType) typeInput.getSelectedItem();
199	                        TokenCalculator.HashAlgorithm algorithm = (TokenCalculator.HashAlgorithm) algorithmInput.getSelectedItem();
200	
201	                        String issuer = issuerInput.getText().toString();
202	                        String label = labelInput.getText().toString();
203	                        //Replace spaces with empty characters
204	                        String secret = secretInput.getText().toString().replaceAll("\\s+","");
205	                        int digits = Integer.parseInt(digitsInput.getText().toString());
206	
207	                        if (type == Entry.OTPType.TOTP || type == Entry.OTPType.STEAM) {
208	                            int period = Integer.parseInt(periodInput.getText().toString());
209	
210	                            Entry e = new Entry(type, secret, period, digits, issuer, label, algorithm, tagsAdapter.getActiveTags());
211	                            e.updateOTP();
212	                            e.setLastUsed(System.currentTimeMillis());
213	                            adapter.addEntry(e);
214	
215	                            callingActivity.refreshTags();
216	                        } else if (type == Entry.OTPType.HOTP) {
217	                            long counter = Long.parseLong(counterInput.getText().toString());
218	
219	                            Entry e = new Entry(type, secret, counter, digits, issuer, label, algorithm, tagsAdapter.getActiveTags());
220	                            e.updateOTP();
221	                            e.setLastUsed(System.currentTimeMillis());
222	                            adapter.addEntry(e);
223	                        }
224	                    }
225	                })
226	                .setNegativeButton(android.R.string.cancel, new DialogInterface.OnClickListener() {
227	                    @Override
228	                    public void onClick(DialogInterface dialogInterface, int i) {}
229	                });
230	
231	        AlertDialog dialog = builder.create();
232	        dialog.show();
233	
234	        final Button positiveButton = dialog.getButton(AlertDialog.BUTTON_POSITIVE);
235	        positiveButton.setEnabled(false);
236	
237	        TextWatcher watcher = new TextWatcher() {
238	            @Override
239	            public void beforeTextChanged(CharSequence charSequence, int i, int i1, int i2) {
240	            }
241	
242	            @Override
243	            public void onTextChanged(CharSequence charSequence, int i, int i1, int i2) {
244	            }
245	
246	            @Override
247	            public void afterTextChanged(Editable editable) {
248	                if (TextUtils.isEmpty(labelInput.getText()) || TextUtils.isEmpty(secretInput.getText())
249	                        || TextUtils.isEmpty(digitsInput.getText()) || Integer.parseInt(digitsInput.getText().toString()) == 0) {
250	                    positiveButton.setEnabled(false);
251	                } else {
252	                    Entry.OTPType type = (Entry.OTPType) typeInput.getSelectedItem();
253	                    if (type == Entry.OTPType.HOTP) {
254	                        if (TextUtils.isEmpty(counterInput.getText())) {
255	                            positiveButton.setEnabled(false);
256	                        } else {
257	                            positiveButton.setEnabled(true);
258	                        }
259	                    } else if (type == Entry.OTPType.TOTP || type == Entry.OTPType.STEAM) {
260	                        if (TextUtils.isEmpty(periodInput.getText()) || Integer.parseInt(periodInput.getText().toString()) == 0) {
261	                            positiveButton.setEnabled(false);
262	                        } else {
263	                            positiveButton.setEnabled(true);
264	                        }
265	                    } else {
266	                        positiveButton.setEnabled(true);
267	                    }
268	                }
269	            }
270	        };
271	
272	        labelInput.addTextChangedListener(watcher);
273	        secretInput.addTextChangedListener(watcher);
274	        periodInput.addTextChangedListener(watcher);
275	        digitsInput.addTextChangedListener(watcher);
276	        counterInput.addTextChangedListener(watcher);
277	    }
278	}
